52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	};
63	
64	const quotePremium = (items: Item[]): number => {
65	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
66	  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
67	};
68	
69	export const runScenario = (scenario: Scenario): ScenarioResult => {
70	  return {
71	    results: scenario.steps.map((step) => ({
72	      premium: quotePremium((step as QuoteStep).items),
73	    })),
74	  };
75	};
